CREATE TABLE "ShopifyCustomerMirror" ("id" TEXT PRIMARY KEY,"shop" TEXT NOT NULL,"firstName" TEXT,"lastName" TEXT,"email" TEXT,"phone" TEXT,"numberOfOrders" INTEGER NOT NULL DEFAULT 0,"amountSpent" DOUBLE PRECISION NOT NULL DEFAULT 0,"currencyCode" TEXT NOT NULL DEFAULT 'INR',"tagsJson" TEXT NOT NULL DEFAULT '[]',"whatsappOptIn" BOOLEAN NOT NULL DEFAULT FALSE,"createdAtShopify" TIMESTAMP(3),"updatedAtShopify" TIMESTAMP(3),"syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "ShopifyCustomerMirror_shop_id_key" ON "ShopifyCustomerMirror"("shop","id");
