CREATE INDEX "ShopifyCustomerMirror_shop_lastName_firstName_idx" ON "ShopifyCustomerMirror"("shop","lastName","firstName");
CREATE TABLE "ShopifyOrderMirror" ("id" TEXT PRIMARY KEY,"shop" TEXT NOT NULL,"customerId" TEXT NOT NULL,"orderName" TEXT NOT NULL,"orderNumber" INTEGER,"processedAt" TIMESTAMP(3),"createdAtShopify" TIMESTAMP(3),"totalPrice" DOUBLE PRECISION NOT NULL DEFAULT 0,"currencyCode" TEXT NOT NULL DEFAULT 'INR',"financialStatus" TEXT,"fulfillmentStatus" TEXT,"lineItemsJson" TEXT NOT NULL DEFAULT '[]',"syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ShopifyOrderMirror_shop_customerId_fkey" FOREIGN KEY ("shop","customerId") REFERENCES "ShopifyCustomerMirror"("shop","id") ON DELETE CASCADE ON UPDATE CASCADE);
