CREATE TABLE "WhatsAppCampaign" ("id" TEXT PRIMARY KEY,"shop" TEXT NOT NULL,"name" TEXT NOT NULL,"templateId" TEXT NOT NULL,"templateName" TEXT NOT NULL,"templateLanguage" TEXT NOT NULL,"templateComponents" TEXT NOT NULL,"variableMappingJson" TEXT NOT NULL DEFAULT '{}',"mediaUrl" TEXT,"scheduledAt" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'DRAFT',"audienceCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
